# backend/app/services/brand.py
# THE LOOK OF EVERY DOCUMENT THE SERVER MAKES: the Smart Apps logo and "Simple Smart Apps Hub" on top, the issuer line below. Mirrors rider-app/src/offline/statementBrand.js.
import re

PROVIDER_NAME = "Simple Smart Apps Hub"
LOGO_DATA_URI = "data:image/png;base64,"
BRAND = {"orange": "#F26B0F", "navy": "#14213D", "ink": "#1F2933", "slate": "#52606D", "line": "#E4E7EB", "orange_soft": "#FFF1E6"}

_CSS = """
.sah-hd{width:100%;border-collapse:collapse;background:#14213D;color:#fff;border-bottom:4px solid #F26B0F;margin-bottom:14px}
.sah-hd td{padding:12px 14px;vertical-align:middle;font-family:Helvetica,Arial,sans-serif}
.sah-name{font-size:17px;font-weight:bold} .sah-app{font-size:10.5px;color:#FFD3B0;text-transform:uppercase;letter-spacing:.6px}
.sah-doc{text-align:right;font-size:13px;font-weight:bold}
.sah-ft{width:100%;border-collapse:collapse;margin-top:22px;border-top:3px solid #F26B0F}
.sah-ft td{padding-top:8px;font-size:9.5px;color:#52606D;text-align:right;font-family:Helvetica,Arial,sans-serif}
"""


def apply_brand(html: str, app: str = "Smart Boda", title: str = "Statement") -> str:
    """Put the logo and provider name on a complete HTML page."""
    header = (
        f'<table class="sah-hd"><tr><td style="width:56px"><img src="{LOGO_DATA_URI}" width="46" height="46" style="border-radius:8px" alt=""/></td>'
        f'<td><div class="sah-name">{PROVIDER_NAME}</div><div class="sah-app">{app}</div></td><td class="sah-doc">{title}</td></tr></table>'
    )
    footer = f'<table class="sah-ft"><tr><td><b style="color:#14213D">{PROVIDER_NAME}</b></td></tr></table>'
    out = re.sub(r"</head>", f"<style>{_CSS}</style></head>", html, count=1, flags=re.I)
    out = re.sub(r"<body[^>]*>", lambda m: m.group(0) + header, out, count=1, flags=re.I)
    out = re.sub(r"</body>", footer + "</body>", out, count=1, flags=re.I)
    return out
